import type { ParkingRule, ParkingSpot } from '../types'
import { publicAssetUrl } from './publicAssets'

/** Per-bay council sign rules, generated by scripts/build_melbourne_bay_zone_rules.py.
 * A bay is mapped to its own council parking zone (from its sensor's
 * zone_number), never to every zone on its road segment. */
export interface BayZoneRules {
  zones: Record<string, ParkingRule[]>
  bays: Record<string, number>
}

let cached: Promise<BayZoneRules> | undefined

export function loadBayZoneRules(): Promise<BayZoneRules> {
  cached ??= fetch(publicAssetUrl('data/melbourne/bay-zone-rules.json'), { signal: AbortSignal.timeout(12000) })
    .then(response => {
      if (!response.ok) throw new Error('Bay sign rules could not load.')
      return response.json() as Promise<BayZoneRules>
    })
    .catch(error => { cached = undefined; throw error })
  return cached
}

/** Evidence a driver or moderator supplied outranks the council import. */
const KEEP: ReadonlySet<NonNullable<ParkingRule['match_method']>> = new Set(['reported', 'field_verified', 'sign_coordinate'])

/** Replace segment-wide rules with the bay's own zone rules where the bay's
 * zone is known. Bays without a known zone keep their existing rules, which
 * the status logic already treats as "read the sign". */
export function applyBayZoneRules(spots: ParkingSpot[], data: BayZoneRules): ParkingSpot[] {
  return spots.map(spot => {
    const zone = spot.kerbside_id ? data.bays[spot.kerbside_id] : undefined
    const rules = zone != null ? data.zones[String(zone)] : undefined
    if (!rules?.length) return spot
    if (spot.rules.some(rule => rule.match_method && KEEP.has(rule.match_method))) return spot
    return { ...spot, rules: rules.map(rule => ({ ...rule })) }
  })
}
